import 'package:mapsindoors/mapsindoors.dart' as MapsIndoors;
import 'package:mapsindoors/mapsindoors_library.dart';

class MapWidget extends StatefulWidget {
  final String apiKey;
  const MapWidget({Key? key, required this.apiKey}) : super(key: key);
  @override
  State<MapWidget> createState() => _MapWidgetState();
}

class _MapWidgetState extends State<MapWidget> {
  final _floorSelector = MPDefaultFloorSelector();
  late final MapsIndoorsWidget _map;
  @override
  void initState() {
    super.initState();
    loadMapsIndoors(widget.apiKey);
  }
  void _ready(MPError? e) async {
    if (e == null) {
      _map.goTo(await getDefaultVenue());
    }
  }
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: _map = MapsIndoorsWidget(
        floorSelector: _floorSelector,
        initialCameraPosition: MPCameraPosition(
          zoom: 7,
          point: MPPoint.withCoordinates(longitude: -118.0165, latitude: 33.9457),
        ),
        readyListener: _ready,
      ),
    );
  }
}
